 ['simple inline',mk({flag:'a'}),{inline:true},null],
 ['simple component',mk({flag:'a'}),{type:'component'},null],
 ['simple scoped',mk({flag:'a'}),{type:'scoped'},null],
 ['ctx transitions',mk({pseudo:'in',name:'@in'}),{},ctx],
 ['global deep',mk({flag:'a'}),{global:true},null],
]) {
