  test('returns null for empty or whitespace-only selectors', () => {
    expect(selparse.parse('')).toBeNull();
    expect(selparse.parse('   \n\t ')).toBeNull();
  });

  test('rewrites a class selector and initializes rule-set metadata', () => {
    const ast = selparse.parse('.one');

    expect(ast).toMatchObject({
      type: 'ruleSet',
      meta: {},
      scopeTo: null,
      media: [],
      container: [],
    });
