    expect(selparse.render(selparse.parse('div.card > a.link'), 'C')).toBe(
      'div.card > a.link:not(._0) {C}'
    );
    expect(selparse.render(selparse.parse('.a >> .b'), 'C')).toBe(
      '.a > .b:not(._0) {C}'
