'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');
const zlib = require('zlib');

/**
 * The production file is authored as an ES module, while the repository is a
 * CommonJS package and has no Babel/Jest transform configured. This small
 * loader evaluates the actual source and its relative ES-module imports as
 * CommonJS in memory, without changing any production file.
 */
function loadInflateModule(entryFile) {
  const cache = new Map();

  function load(fileName) {
    const resolved = path.resolve(fileName);
    if (cache.has(resolved)) {
      return cache.get(resolved).exports;
    }

    let source = fs.readFileSync(resolved, 'utf8');
    const namedExports = [];
    let defaultExport = null;

    source = source.replace(
      /^export\s+default\s+function\s+([A-Za-z_$][\w$]*)/gm,
      (_, name) => {
        defaultExport = name;
        return `function ${name}`;
      }
    );
    source = source.replace(
      /^export\s+default\s+([A-Za-z_$][\w$]*)\s*;?/gm,
      (_, name) => {
        defaultExport = name;
        return '';
      }
    );
    source = source.replace(
      /^export\s+(function|var|const|let)\s+([A-Za-z_$][\w$]*)/gm,
      (_, kind, name) => {
        namedExports.push(name);
        return `${kind} ${name}`;
      }
    );
    source = source.replace(
      /^import\s+\{([^}]+)\}\s+from\s+(['"])([^'"]+)\2\s*;?/gm,
      (_, names, quote, specifier) => `const {${names}} = require(${JSON.stringify(specifier)});`
    );
    source = source.replace(
      /^import\s+([A-Za-z_$][\w$]*)\s+from\s+(['"])([^'"]+)\2\s*;?/gm,
      (_, name, quote, specifier) => `const ${name} = require(${JSON.stringify(specifier)}).default;`
    );

    source += '\n';
    for (const name of namedExports) {
      source += `exports.${name} = ${name};\n`;
    }
    if (defaultExport) {
      source += `exports.default = ${defaultExport};\n`;
    }

    const module = { exports: {} };
    cache.set(resolved, module);

    const localRequire = (specifier) => {
      if (specifier.startsWith('.')) {
        let dependency = path.resolve(path.dirname(resolved), specifier);
        if (!path.extname(dependency)) {
          dependency += '.js';
        }
        return load(dependency);
      }
      return require(specifier);
    };

    const wrapper = vm.runInThisContext(
      `(function (exports, require, module, __filename, __dirname) {\n${source}\n})`,
      { filename: resolved }
    );
    wrapper(module.exports, localRequire, module, resolved, path.dirname(resolved));
    return module.exports;
  }

  return load(entryFile);
}

const targetPath = path.resolve(
  __dirname,
  '../../../../../packages/imba/polyfills/zlib/zlib-lib/inflate.js'
);
const inflateApi = loadInflateModule(targetPath);

const Z_OK = 0;
const Z_STREAM_END = 1;
const Z_NEED_DICT = 2;
const Z_STREAM_ERROR = -2;
const Z_DATA_ERROR = -3;
const Z_BUF_ERROR = -5;
const Z_NO_FLUSH = 0;
const Z_FINISH = 4;
const Z_BLOCK = 5;
const Z_TREES = 6;

const SAMPLE = 'The quick brown fox jumps over the lazy dog. '.repeat(6) +
  'Compression should preserve every byte, including unicode: \u03bb\u03b1\u03b2\u03b3.';
const SAMPLE_BYTES = Buffer.from(SAMPLE, 'utf8');

function adler32u(bytes) {
  let a = 1;
  let b = 0;
  for (const byte of bytes) {
    a = (a + byte) % 65521;
    b = (b + a) % 65521;
  }
  return (((b << 16) | a) >>> 0);
}

function crc32u(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) {
      crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
    }
  }
  return ((crc ^ 0xffffffff) >>> 0);
}

function makeStream(input, outputLength) {
  const inputBytes = Uint8Array.from(input);
  return {
    input: inputBytes,
    avail_in: inputBytes.length,
    next_in: 0,
    output: new Uint8Array(outputLength),
    avail_out: outputLength,
    next_out: 0
  };
}

function initializedStream(input, outputLength, windowBits) {
  const strm = makeStream(input, outputLength);
  const ret = windowBits === undefined
    ? inflateApi.inflateInit(strm)
    : inflateApi.inflateInit2(strm, windowBits);
  if (ret !== Z_OK) {
    throw new Error(`inflate initialization failed with ${ret}`);
  }
  return strm;
}

function producedBytes(strm) {
  return Buffer.from(strm.output.subarray(0, strm.output.length - strm.avail_out));
}

function inflateWhole(compressed, windowBits, outputLength) {
  const strm = initializedStream(compressed, outputLength, windowBits);
  const ret = inflateApi.inflate(strm, Z_FINISH);
  return { strm, ret, output: producedBytes(strm) };
}

function rawStoredBlock(bytes) {
  const length = bytes.length;
  if (length > 0xffff) {
    throw new Error('stored block fixture is too large');
  }
  const header = Buffer.from([
    0x01,
    length & 0xff,
    (length >>> 8) & 0xff,
    (~length) & 0xff,
    ((~length) >>> 8) & 0xff
  ]);
  return Buffer.concat([header, Buffer.from(bytes)]);
}

function makeGzipHeader({ flags = 0, mtime = 0, xflags = 0, os = 3 } = {}) {
  const header = Buffer.alloc(10);
  header[0] = 0x1f;
  header[1] = 0x8b;
  header[2] = 8;
  header[3] = flags;
  header.writeUInt32LE(mtime >>> 0, 4);
  header[8] = xflags;
  header[9] = os;
  return header;
}

function emptyGzipHeader() {
  return {
    text: 0,
    time: 0,
    xflags: 0,
    os: 0,
    extra: null,
    extra_len: 0,
    name: '',
    comment: '',
    hcrc: 0,
    done: false
  };
}

describe('inflate module public surface', () => {
  it('exports the inflate API and identifying metadata', () => {
    expect(Object.keys(inflateApi).sort()).toEqual([
      'inflate',
      'inflateEnd',
      'inflateGetHeader',
      'inflateInfo',
      'inflateInit',
      'inflateInit2',
      'inflateReset',
      'inflateReset2',
      'inflateResetKeep',
      'inflateSetDictionary'
    ]);
    expect(inflateApi.inflateInfo).toBe('pako inflate (from Nodeca project)');
    for (const name of [
      'inflate',
      'inflateEnd',
      'inflateGetHeader',
      'inflateInit',
      'inflateInit2',
      'inflateReset',
      'inflateReset2',
      'inflateResetKeep',
      'inflateSetDictionary'
    ]) {
      expect(typeof inflateApi[name]).toBe('function');
    }
  });
});

describe('initialization and reset', () => {
  it('initializes a default zlib stream and exposes the expected initial state', () => {
    const strm = {};

    expect(inflateApi.inflateInit(strm)).toBe(Z_OK);

    expect(strm.total_in).toBe(0);
    expect(strm.total_out).toBe(0);
    expect(strm.adler).toBe(1);
    expect(strm.msg).toBe('');
    expect(strm.state).toMatchObject({
      mode: 1,
      last: false,
      wrap: 1,
      havedict: false,
      dmax: 32768,
      wbits: 15,
      wsize: 0,
      whave: 0,
      wnext: 0,
      window: null,
      hold: 0,
      bits: 0,
      sane: 1,
      back: -1
    });
    expect(strm.state.lencode).toBe(strm.state.lendyn);
    expect(strm.state.distcode).toBe(strm.state.distdyn);
    expect(strm.state.lencode).toHaveLength(852);
    expect(strm.state.distcode).toHaveLength(592);
  });

  it('maps windowBits to raw, zlib, gzip, and automatic wrapper modes', () => {
    const strm = {};

    expect(inflateApi.inflateInit2(strm, -15)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 0, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 15)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 1, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 31)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 2, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 47)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 3, wbits: 15 });
  });

  it('rejects invalid streams and invalid window sizes', () => {
    expect(inflateApi.inflateInit(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateInit2(undefined, 15)).toBe(Z_STREAM_ERROR);

    const invalidSmall = {};
    expect(inflateApi.inflateInit2(invalidSmall, 7)).toBe(Z_STREAM_ERROR);
    expect(invalidSmall.state).toBeNull();

    const invalidMiddle = {};
    expect(inflateApi.inflateInit2(invalidMiddle, 23)).toBe(Z_STREAM_ERROR);
    expect(invalidMiddle.state).toBeNull();

    const initialized = {};
    expect(inflateApi.inflateInit(initialized)).toBe(Z_OK);
    expect(inflateApi.inflateReset2(initialized, -8)).toBe(Z_OK);
    expect(inflateApi.inflateReset2(initialized, 7)).toBe(Z_STREAM_ERROR);
    expect(initialized.state.wbits).toBe(8);
  });

  it('inflateResetKeep clears counters, checksum state, and decoding tables', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, SAMPLE_BYTES.length + 32, 15);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    const state = strm.state;
    const previousLencode = state.lencode;
    strm.msg = 'stale message';

    expect(inflateApi.inflateResetKeep(strm)).toBe(Z_OK);

    expect(strm.total_in).toBe(0);
    expect(strm.total_out).toBe(0);
    expect(strm.adler).toBe(1);
    expect(strm.msg).toBe('');
    expect(state).toMatchObject({
      mode: 1,
      last: 0,
      havedict: 0,
      dmax: 32768,
      hold: 0,
      bits: 0,
      sane: 1,
      back: -1,
      head: null
    });
    expect(state.lencode).not.toBe(previousLencode);
    expect(state.lencode).toBe(state.lendyn);
    expect(state.distcode).toBe(state.distdyn);
  });

  it('inflateReset clears sliding-window counters while retaining the allocation', () => {
    const dictionary = Buffer.from('shared sliding window dictionary');
    const strm = initializedStream(Buffer.alloc(0), 32, -15);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);

    const window = strm.state.window;
    expect(window).toBeInstanceOf(Uint8Array);
    expect(strm.state.wsize).toBe(1 << 15);
    expect(strm.state.whave).toBe(dictionary.length);
    expect(strm.state.wnext).toBe(dictionary.length);

    expect(inflateApi.inflateReset(strm)).toBe(Z_OK);
    expect(strm.state.window).toBe(window);
    expect(strm.state.wsize).toBe(0);
    expect(strm.state.whave).toBe(0);
    expect(strm.state.wnext).toBe(0);
  });

  it('frees the window when inflateReset2 changes the window size', () => {
    const dictionary = Buffer.from('window resize dictionary');
    const strm = initializedStream(Buffer.alloc(0), 32, -15);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);
    const window = strm.state.window;

    expect(inflateApi.inflateReset2(strm, -15)).toBe(Z_OK);
    expect(strm.state.window).toBe(window);

    expect(inflateApi.inflateReset2(strm, -14)).toBe(Z_OK);
    expect(strm.state.window).toBeNull();
    expect(strm.state.wbits).toBe(14);
  });

  it('rejects reset calls without a stream state', () => {
    expect(inflateApi.inflateResetKeep(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateResetKeep({})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset({})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset2(null, 15)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset2({}, 15)).toBe(Z_STREAM_ERROR);
  });
});

describe('inflate state machine and output paths', () => {
  it('inflates a complete zlib stream and reports counters/checksum', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const { strm, ret, output } = inflateWhole(
      compressed,
      15,
      SAMPLE_BYTES.length + 64
    );

    expect(ret).toBe(Z_STREAM_END);
    expect(output.toString('utf8')).toBe(SAMPLE);
    expect(strm.avail_in).toBe(0);
    expect(strm.next_in).toBe(compressed.length);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
