'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');
const zlib = require('zlib');

/**
 * The production file is authored as an ES module, while the repository is a
 * CommonJS package and has no Babel/Jest transform configured. This small
 * loader evaluates the actual source and its relative ES-module imports as
 * CommonJS in memory, without changing any production file.
 */
function loadInflateModule(entryFile) {
  const cache = new Map();

  function load(fileName) {
    const resolved = path.resolve(fileName);
    if (cache.has(resolved)) {
      return cache.get(resolved).exports;
    }

    let source = fs.readFileSync(resolved, 'utf8');
    const namedExports = [];
    let defaultExport = null;

    source = source.replace(
      /^export\s+default\s+function\s+([A-Za-z_$][\w$]*)/gm,
      (_, name) => {
        defaultExport = name;
        return `function ${name}`;
      }
    );
    source = source.replace(
      /^export\s+default\s+([A-Za-z_$][\w$]*)\s*;?/gm,
      (_, name) => {
        defaultExport = name;
        return '';
      }
    );
    source = source.replace(
      /^export\s+(function|var|const|let)\s+([A-Za-z_$][\w$]*)/gm,
      (_, kind, name) => {
        namedExports.push(name);
        return `${kind} ${name}`;
      }
    );
    source = source.replace(
      /^import\s+\{([^}]+)\}\s+from\s+(['"])([^'"]+)\2\s*;?/gm,
      (_, names, quote, specifier) => `const {${names}} = require(${JSON.stringify(specifier)});`
    );
    source = source.replace(
      /^import\s+([A-Za-z_$][\w$]*)\s+from\s+(['"])([^'"]+)\2\s*;?/gm,
      (_, name, quote, specifier) => `const ${name} = require(${JSON.stringify(specifier)}).default;`
    );

    source += '\n';
    for (const name of namedExports) {
      source += `exports.${name} = ${name};\n`;
    }
    if (defaultExport) {
      source += `exports.default = ${defaultExport};\n`;
    }

    const module = { exports: {} };
    cache.set(resolved, module);

    const localRequire = (specifier) => {
      if (specifier.startsWith('.')) {
        let dependency = path.resolve(path.dirname(resolved), specifier);
        if (!path.extname(dependency)) {
          dependency += '.js';
        }
        return load(dependency);
      }
      return require(specifier);
    };

    const wrapper = vm.runInThisContext(
      `(function (exports, require, module, __filename, __dirname) {\n${source}\n})`,
      { filename: resolved }
    );
    wrapper(module.exports, localRequire, module, resolved, path.dirname(resolved));
    return module.exports;
  }

  return load(entryFile);
}

const targetPath = path.resolve(
  __dirname,
  '../../../../../packages/imba/polyfills/zlib/zlib-lib/inflate.js'
);
const inflateApi = loadInflateModule(targetPath);

const Z_OK = 0;
const Z_STREAM_END = 1;
const Z_NEED_DICT = 2;
const Z_STREAM_ERROR = -2;
const Z_DATA_ERROR = -3;
const Z_BUF_ERROR = -5;
const Z_NO_FLUSH = 0;
const Z_FINISH = 4;
const Z_BLOCK = 5;
const Z_TREES = 6;

const SAMPLE = 'The quick brown fox jumps over the lazy dog. '.repeat(6) +
  'Compression should preserve every byte, including unicode: \u03bb\u03b1\u03b2\u03b3.';
const SAMPLE_BYTES = Buffer.from(SAMPLE, 'utf8');

function adler32u(bytes) {
  let a = 1;
  let b = 0;
  for (const byte of bytes) {
    a = (a + byte) % 65521;
    b = (b + a) % 65521;
  }
  return (((b << 16) | a) >>> 0);
}

function crc32u(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) {
      crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
    }
  }
  return ((crc ^ 0xffffffff) >>> 0);
}

function makeStream(input, outputLength) {
  const inputBytes = Uint8Array.from(input);
  return {
    input: inputBytes,
    avail_in: inputBytes.length,
    next_in: 0,
    output: new Uint8Array(outputLength),
    avail_out: outputLength,
    next_out: 0
  };
