function makeGzipHeader({ flags = 0, mtime = 0, xflags = 0, os = 3 } = {}) {
  const header = Buffer.alloc(10);
  header[0] = 0x1f;
  header[1] = 0x8b;
  header[2] = 8;
  header[3] = flags;
  header.writeUInt32LE(mtime >>> 0, 4);
  header[8] = xflags;
  header[9] = os;
  return header;
}

function emptyGzipHeader() {
  return {
    text: 0,
    time: 0,
    xflags: 0,
    os: 0,
    extra: null,
    extra_len: 0,
    name: '',
    comment: '',
    hcrc: 0,
    done: false
  };
}

