describe('initialization and reset', () => {
  it('initializes a default zlib stream and exposes the expected initial state', () => {
    const strm = {};

    expect(inflateApi.inflateInit(strm)).toBe(Z_OK);

    expect(strm.total_in).toBe(0);
    expect(strm.total_out).toBe(0);
    expect(strm.adler).toBe(1);
    expect(strm.msg).toBe('');
    expect(strm.state).toMatchObject({
      mode: 1,
      last: false,
      wrap: 1,
      havedict: false,
      dmax: 32768,
      wbits: 15,
      wsize: 0,
      whave: 0,
      wnext: 0,
      window: null,
      hold: 0,
      bits: 0,
      sane: 1,
      back: -1
    });
    expect(strm.state.lencode).toBe(strm.state.lendyn);
    expect(strm.state.distcode).toBe(strm.state.distdyn);
    expect(strm.state.lencode).toHaveLength(852);
    expect(strm.state.distcode).toHaveLength(592);
  });

  it('maps windowBits to raw, zlib, gzip, and automatic wrapper modes', () => {
    const strm = {};

    expect(inflateApi.inflateInit2(strm, -15)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 0, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 15)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 1, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 31)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 2, wbits: 15 });

    expect(inflateApi.inflateReset2(strm, 47)).toBe(Z_OK);
    expect(strm.state).toMatchObject({ wrap: 3, wbits: 15 });
  });

  it('rejects invalid streams and invalid window sizes', () => {
    expect(inflateApi.inflateInit(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateInit2(undefined, 15)).toBe(Z_STREAM_ERROR);

    const invalidSmall = {};
    expect(inflateApi.inflateInit2(invalidSmall, 7)).toBe(Z_STREAM_ERROR);
    expect(invalidSmall.state).toBeNull();

    const invalidMiddle = {};
    expect(inflateApi.inflateInit2(invalidMiddle, 23)).toBe(Z_STREAM_ERROR);
    expect(invalidMiddle.state).toBeNull();

    const initialized = {};
    expect(inflateApi.inflateInit(initialized)).toBe(Z_OK);
    expect(inflateApi.inflateReset2(initialized, -8)).toBe(Z_OK);
    expect(inflateApi.inflateReset2(initialized, 7)).toBe(Z_STREAM_ERROR);
    expect(initialized.state.wbits).toBe(8);
  });

  it('inflateResetKeep clears counters, checksum state, and decoding tables', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, SAMPLE_BYTES.length + 32, 15);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    const state = strm.state;
    const previousLencode = state.lencode;
    strm.msg = 'stale message';

    expect(inflateApi.inflateResetKeep(strm)).toBe(Z_OK);

    expect(strm.total_in).toBe(0);
    expect(strm.total_out).toBe(0);
    expect(strm.adler).toBe(1);
    expect(strm.msg).toBe('');
    expect(state).toMatchObject({
      mode: 1,
      last: 0,
      havedict: 0,
      dmax: 32768,
      hold: 0,
      bits: 0,
      sane: 1,
      back: -1,
      head: null
    });
    expect(state.lencode).not.toBe(previousLencode);
    expect(state.lencode).toBe(state.lendyn);
    expect(state.distcode).toBe(state.distdyn);
  });

  it('inflateReset clears sliding-window counters while retaining the allocation', () => {
    const dictionary = Buffer.from('shared sliding window dictionary');
    const strm = initializedStream(Buffer.alloc(0), 32, -15);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);

    const window = strm.state.window;
    expect(window).toBeInstanceOf(Uint8Array);
    expect(strm.state.wsize).toBe(1 << 15);
    expect(strm.state.whave).toBe(dictionary.length);
    expect(strm.state.wnext).toBe(dictionary.length);

    expect(inflateApi.inflateReset(strm)).toBe(Z_OK);
    expect(strm.state.window).toBe(window);
    expect(strm.state.wsize).toBe(0);
    expect(strm.state.whave).toBe(0);
    expect(strm.state.wnext).toBe(0);
  });

  it('frees the window when inflateReset2 changes the window size', () => {
    const dictionary = Buffer.from('window resize dictionary');
    const strm = initializedStream(Buffer.alloc(0), 32, -15);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);
    const window = strm.state.window;

    expect(inflateApi.inflateReset2(strm, -15)).toBe(Z_OK);
    expect(strm.state.window).toBe(window);

    expect(inflateApi.inflateReset2(strm, -14)).toBe(Z_OK);
    expect(strm.state.window).toBeNull();
    expect(strm.state.wbits).toBe(14);
  });

  it('rejects reset calls without a stream state', () => {
    expect(inflateApi.inflateResetKeep(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateResetKeep({})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset({})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset2(null, 15)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateReset2({}, 15)).toBe(Z_STREAM_ERROR);
  });
});

describe('inflate state machine and output paths', () => {
  it('inflates a complete zlib stream and reports counters/checksum', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const { strm, ret, output } = inflateWhole(
      compressed,
      15,
      SAMPLE_BYTES.length + 64
    );

    expect(ret).toBe(Z_STREAM_END);
    expect(output.toString('utf8')).toBe(SAMPLE);
    expect(strm.avail_in).toBe(0);
    expect(strm.next_in).toBe(compressed.length);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
    expect(strm.adler >>> 0).toBe(adler32u(SAMPLE_BYTES));
    expect(strm.msg).toBe('');
    expect(strm.data_type).toBe(64);
  });

  it('inflates a raw deflate stream', () => {
    const compressed = zlib.deflateRawSync(SAMPLE_BYTES);
    const { strm, ret, output } = inflateWhole(
      compressed,
      -15,
      SAMPLE_BYTES.length + 64
    );

    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.state.wrap).toBe(0);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
  });

  it('inflates a gzip stream and validates its checksums', () => {
    const compressed = zlib.gzipSync(SAMPLE_BYTES);
    const { strm, ret, output } = inflateWhole(
      compressed,
      31,
      SAMPLE_BYTES.length + 64
    );

    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.state.wrap).toBe(2);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
    expect(strm.adler >>> 0).toBe(crc32u(SAMPLE_BYTES));
  });

  it.each([
    ['zlib', 15, (data) => zlib.deflateSync(data)],
    ['gzip', 31, (data) => zlib.gzipSync(data)]
  ])('auto-detects a %s stream with windowBits=47', (_label, _bits, compress) => {
    const compressed = compress(SAMPLE_BYTES);
    const { strm, ret, output } = inflateWhole(
      compressed,
      47,
      SAMPLE_BYTES.length + 64
    );

    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.state.wrap).toBe(3);
  });

  it('decodes a fixed-Huffman block', () => {
    const compressed = zlib.deflateRawSync(SAMPLE_BYTES, {
      strategy: zlib.constants.Z_FIXED
    });
    const blockType = compressed[0] & 0x07;
    const { ret, output } = inflateWhole(
      compressed,
      -15,
      SAMPLE_BYTES.length + 64
    );

    expect(blockType).toBe(3); // BFINAL=1, BTYPE=01 (fixed Huffman)
    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(SAMPLE_BYTES)).toBe(true);
  });

  it('decodes a dynamic-Huffman block built by the dynamic table path', () => {
    const longText = Array.from(
      { length: 400 },
      (_, index) => `line ${index}: quick brown fox ${index * 7 % 23}\n`
    ).join('');
    const source = Buffer.from(longText);
    const compressed = zlib.deflateRawSync(source);
    const blockType = compressed[0] & 0x07;

    const { ret, output } = inflateWhole(compressed, -15, source.length + 64);

    expect(blockType).toBe(5); // BFINAL=1, BTYPE=10 (dynamic Huffman)
    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(source)).toBe(true);
  });

  it('decodes a stored block', () => {
    const source = Buffer.from('Stored blocks are copied without Huffman coding.');
    const compressed = rawStoredBlock(source);
    const { ret, output } = inflateWhole(compressed, -15, source.length + 16);

    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(source)).toBe(true);
  });

  it('handles an empty zlib stream', () => {
    const compressed = zlib.deflateSync(Buffer.alloc(0));
    const { strm, ret, output } = inflateWhole(compressed, 15, 0);

    expect(ret).toBe(Z_STREAM_END);
    expect(output).toHaveLength(0);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(0);
  });

  it('consumes a stream fed one input byte at a time', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const strm = makeStream(Buffer.alloc(0), SAMPLE_BYTES.length + 64);
    expect(inflateApi.inflateInit(strm)).toBe(Z_OK);

    const returns = [];
    for (let index = 0; index < compressed.length; index++) {
      strm.input = Uint8Array.of(compressed[index]);
      strm.avail_in = 1;
      strm.next_in = 0;
      returns.push(inflateApi.inflate(strm, Z_NO_FLUSH));
    }

    expect(returns.slice(0, -1)).toEqual(new Array(compressed.length - 1).fill(Z_OK));
    expect(returns[returns.length - 1]).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.total_in).toBe(compressed.length);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
  });

  it('produces the same output through a very small output buffer', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, 5, 15);
    const chunks = [];
    const returns = [];

    for (let guard = 0; guard < 10000; guard++) {
      returns.push(inflateApi.inflate(strm, Z_FINISH));
      chunks.push(producedBytes(strm));
      if (returns[returns.length - 1] !== Z_OK &&
          returns[returns.length - 1] !== Z_BUF_ERROR) {
        break;
      }
      strm.output = new Uint8Array(5);
      strm.avail_out = 5;
      strm.next_out = 0;
    }

    expect(returns[returns.length - 1]).toBe(Z_STREAM_END);
    expect(returns.slice(0, -1).every((status) => status === Z_BUF_ERROR)).toBe(true);
    expect(Buffer.concat(chunks).equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
  });

  it('leaves bytes following the end of the compressed stream untouched', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const trailing = Buffer.from([0xde, 0xad, 0xbe, 0xef]);
    const input = Buffer.concat([compressed, trailing]);
    const { strm, ret, output } = inflateWhole(input, 15, SAMPLE_BYTES.length + 64);

    expect(ret).toBe(Z_STREAM_END);
    expect(output.equals(SAMPLE_BYTES)).toBe(true);
    expect(strm.avail_in).toBe(trailing.length);
    expect(strm.next_in).toBe(compressed.length);
    expect(strm.total_in).toBe(compressed.length);
  });

  it('resumes successfully after a truncated trailer causes no progress', () => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const trailer = compressed.subarray(compressed.length - 4);
    const truncated = compressed.subarray(0, compressed.length - 4);
    const strm = initializedStream(truncated, SAMPLE_BYTES.length + 64, 15);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_BUF_ERROR);
    expect(strm.total_out).toBe(SAMPLE_BYTES.length);
    expect(strm.msg).toBe('');

    strm.input = Uint8Array.from(trailer);
    strm.avail_in = trailer.length;
    strm.next_in = 0;
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
  });

  it.each([
    ['Z_BLOCK', Z_BLOCK],
    ['Z_TREES', Z_TREES]
  ])('supports %s flush boundaries', (_label, flush) => {
    const compressed = zlib.deflateSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, SAMPLE_BYTES.length + 64, 15);

    const first = inflateApi.inflate(strm, flush);
    expect(first).toBe(Z_OK);
    expect(strm.total_out).toBe(0);

    let status = first;
    for (let guard = 0; guard < 20 && status === Z_OK; guard++) {
      status = inflateApi.inflate(strm, flush);
    }

    expect(status).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
  });

  it('returns Z_BUF_ERROR when a call can make no progress', () => {
    const strm = makeStream(Buffer.alloc(0), 32);
    expect(inflateApi.inflateInit(strm)).toBe(Z_OK);
    expect(inflateApi.inflate(strm, Z_NO_FLUSH)).toBe(Z_BUF_ERROR);
  });
});

describe('invalid streams and compressed data', () => {
  it('rejects malformed stream objects', () => {
    expect(inflateApi.inflate(null, Z_FINISH)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflate({}, Z_FINISH)).toBe(Z_STREAM_ERROR);

    const noOutput = initializedStream(zlib.deflateSync(Buffer.from('x')), 16, 15);
    noOutput.output = null;
    expect(inflateApi.inflate(noOutput, Z_FINISH)).toBe(Z_STREAM_ERROR);

    const missingInput = initializedStream(zlib.deflateSync(Buffer.from('x')), 16, 15);
    missingInput.input = null;
    missingInput.avail_in = 1;
    expect(inflateApi.inflate(missingInput, Z_FINISH)).toBe(Z_STREAM_ERROR);
  });

  it.each([
    {
      name: 'bad zlib header check',
      windowBits: 15,
      input: (() => {
        const bytes = Buffer.from(zlib.deflateSync(SAMPLE_BYTES));
        bytes[0] ^= 0x01;
        return bytes;
      })(),
      message: 'incorrect header check'
    },
    {
      name: 'unknown compression method',
      windowBits: 15,
      input: Buffer.from([0x77, 0x09, 0x00, 0x00, 0x00, 0x00]),
      message: 'unknown compression method'
    },
    {
      name: 'window larger than requested',
      windowBits: 8,
      input: zlib.deflateSync(SAMPLE_BYTES),
      message: 'invalid window size'
    },
    {
      name: 'invalid block type',
      windowBits: 15,
      input: Buffer.from([0x78, 0x9c, 0x07, 0x00, 0x00, 0x00, 0x00]),
      message: 'invalid block type'
    },
    {
      name: 'invalid stored block lengths',
      windowBits: 15,
      input: Buffer.from([0x78, 0x9c, 0x01, 0x05, 0x00, 0x00, 0x00]),
      message: 'invalid stored block lengths'
    }
  ])('reports $name as a data error', ({ windowBits, input, message }) => {
    const strm = initializedStream(input, 128, windowBits);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe(message);
  });

  it('detects a bad zlib Adler-32 trailer', () => {
    const bytes = Buffer.from(zlib.deflateSync(SAMPLE_BYTES));
    bytes[bytes.length - 1] ^= 0x01;
    const strm = initializedStream(bytes, SAMPLE_BYTES.length + 64, 15);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect data check');
  });

  it('detects a bad gzip CRC-32 trailer', () => {
    const bytes = Buffer.from(zlib.gzipSync(SAMPLE_BYTES));
    bytes[bytes.length - 8] ^= 0x01;
    const strm = initializedStream(bytes, SAMPLE_BYTES.length + 64, 31);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect data check');
  });

  it('detects a bad gzip uncompressed-length trailer', () => {
    const bytes = Buffer.from(zlib.gzipSync(SAMPLE_BYTES));
    bytes[bytes.length - 4] ^= 0x01;
    const strm = initializedStream(bytes, SAMPLE_BYTES.length + 64, 31);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe('incorrect length check');
  });
});

describe('gzip header handling', () => {
  it('reports basic gzip header metadata and completion', () => {
    const compressed = zlib.gzipSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, SAMPLE_BYTES.length + 64, 31);
    const header = emptyGzipHeader();

    expect(inflateApi.inflateGetHeader(strm, header)).toBe(Z_OK);
    expect(header.done).toBe(false);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
    expect(header).toMatchObject({
      text: 0,
      time: 0,
      xflags: 0,
      os: 3,
      extra: null,
      name: null,
      comment: null,
      hcrc: 0,
      done: true
    });
  });

  it('parses optional gzip extra, name, comment, and text fields', () => {
    const original = zlib.gzipSync(SAMPLE_BYTES);
    const flags = 0x01 | 0x04 | 0x08 | 0x10; // text, extra, name, comment
    const header = makeGzipHeader({ flags, mtime: 0x04030201, xflags: 2, os: 3 });
    const extra = Buffer.from([4, 0, 9, 8, 7, 6]);
    const name = Buffer.from('archive.txt\0', 'latin1');
    const comment = Buffer.from('generated\0', 'latin1');
    const custom = Buffer.concat([header, extra, name, comment, original.subarray(10)]);

    const strm = initializedStream(custom, SAMPLE_BYTES.length + 64, 31);
    const parsed = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(strm, parsed)).toBe(Z_OK);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
    expect(parsed).toMatchObject({
      text: 1,
      time: 0x04030201,
      xflags: 2,
      os: 3,
      extra: [9, 8, 7, 6],
      extra_len: 4,
      name: 'archive.txt',
      comment: 'generated',
      hcrc: 0,
      done: true
    });
  });

  it('validates and reports a gzip header CRC', () => {
    const original = zlib.gzipSync(SAMPLE_BYTES);
    const header = makeGzipHeader({ flags: 0x02 });
    const headerCrc = crc32u(header);
    const valid = Buffer.concat([
      header,
      Buffer.from([headerCrc & 0xff, (headerCrc >>> 8) & 0xff]),
      original.subarray(10)
    ]);

    const strm = initializedStream(valid, SAMPLE_BYTES.length + 64, 31);
    const parsed = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(strm, parsed)).toBe(Z_OK);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(parsed.hcrc).toBe(1);
    expect(parsed.done).toBe(true);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);

    const corrupted = Buffer.from(valid);
    corrupted[10] ^= 0x01;
    const badStrm = initializedStream(corrupted, SAMPLE_BYTES.length + 64, 31);
    const badHeader = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(badStrm, badHeader)).toBe(Z_OK);
    expect(inflateApi.inflate(badStrm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(badStrm.msg).toBe('header crc mismatch');
    expect(badHeader.done).toBe(false);
  });

  it.each([
    ['unknown gzip compression method', [0x1f, 0x8b, 0x07, 0x00, 0, 0, 0, 0, 0, 3], 'unknown compression method'],
    ['reserved gzip flags', [0x1f, 0x8b, 0x08, 0x20, 0, 0, 0, 0, 0, 3], 'unknown header flags set']
  ])('reports %s', (_name, bytes, message) => {
    const strm = initializedStream(Buffer.from(bytes), 64, 31);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe(message);
  });

  it('rejects header requests for non-gzip or invalid streams', () => {
    expect(inflateApi.inflateGetHeader(null, {})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateGetHeader({}, {})).toBe(Z_STREAM_ERROR);

    const zlibStrm = initializedStream(zlib.deflateSync(Buffer.from('x')), 16, 15);
    const header = { done: true };
    expect(inflateApi.inflateGetHeader(zlibStrm, header)).toBe(Z_STREAM_ERROR);
    expect(header.done).toBe(true);
  });
});

describe('dictionary handling', () => {
  const dictionary = Buffer.from('hello world dictionary');
  const dictionaryData = Buffer.from(
    'hello world from the dictionary hello world!'
  );

  it('requests a dictionary, rejects the wrong one, and accepts the right one', () => {
    const compressed = zlib.deflateSync(dictionaryData, { dictionary });
    const strm = initializedStream(compressed, dictionaryData.length + 64, 15);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_NEED_DICT);
    expect(strm.total_out).toBe(0);
    expect(strm.state.mode).toBe(11); // DICT

    expect(inflateApi.inflateSetDictionary(strm, Buffer.from('wrong'))).toBe(Z_DATA_ERROR);
    expect(strm.state.mode).toBe(11);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);
    expect(strm.state.havedict).toBe(1);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(dictionaryData)).toBe(true);
  });

  it('accepts a preset dictionary for a raw deflate stream', () => {
    const compressed = zlib.deflateRawSync(dictionaryData, { dictionary });
    const strm = initializedStream(compressed, dictionaryData.length + 64, -15);

