describe('gzip header handling', () => {
  it('reports basic gzip header metadata and completion', () => {
    const compressed = zlib.gzipSync(SAMPLE_BYTES);
    const strm = initializedStream(compressed, SAMPLE_BYTES.length + 64, 31);
    const header = emptyGzipHeader();

    expect(inflateApi.inflateGetHeader(strm, header)).toBe(Z_OK);
    expect(header.done).toBe(false);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
    expect(header).toMatchObject({
      text: 0,
      time: 0,
      xflags: 0,
      os: 3,
      extra: null,
      name: null,
      comment: null,
      hcrc: 0,
      done: true
    });
  });

  it('parses optional gzip extra, name, comment, and text fields', () => {
    const original = zlib.gzipSync(SAMPLE_BYTES);
    const flags = 0x01 | 0x04 | 0x08 | 0x10; // text, extra, name, comment
    const header = makeGzipHeader({ flags, mtime: 0x04030201, xflags: 2, os: 3 });
    const extra = Buffer.from([4, 0, 9, 8, 7, 6]);
    const name = Buffer.from('archive.txt\0', 'latin1');
    const comment = Buffer.from('generated\0', 'latin1');
    const custom = Buffer.concat([header, extra, name, comment, original.subarray(10)]);

    const strm = initializedStream(custom, SAMPLE_BYTES.length + 64, 31);
    const parsed = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(strm, parsed)).toBe(Z_OK);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);

    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);
    expect(parsed).toMatchObject({
      text: 1,
      time: 0x04030201,
      xflags: 2,
      os: 3,
      extra: [9, 8, 7, 6],
      extra_len: 4,
      name: 'archive.txt',
      comment: 'generated',
      hcrc: 0,
      done: true
    });
  });

  it('validates and reports a gzip header CRC', () => {
    const original = zlib.gzipSync(SAMPLE_BYTES);
    const header = makeGzipHeader({ flags: 0x02 });
    const headerCrc = crc32u(header);
    const valid = Buffer.concat([
      header,
      Buffer.from([headerCrc & 0xff, (headerCrc >>> 8) & 0xff]),
      original.subarray(10)
    ]);

    const strm = initializedStream(valid, SAMPLE_BYTES.length + 64, 31);
    const parsed = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(strm, parsed)).toBe(Z_OK);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(parsed.hcrc).toBe(1);
    expect(parsed.done).toBe(true);
    expect(producedBytes(strm).equals(SAMPLE_BYTES)).toBe(true);

    const corrupted = Buffer.from(valid);
    corrupted[10] ^= 0x01;
    const badStrm = initializedStream(corrupted, SAMPLE_BYTES.length + 64, 31);
    const badHeader = emptyGzipHeader();
    expect(inflateApi.inflateGetHeader(badStrm, badHeader)).toBe(Z_OK);
    expect(inflateApi.inflate(badStrm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(badStrm.msg).toBe('header crc mismatch');
    expect(badHeader.done).toBe(false);
  });

  it.each([
    ['unknown gzip compression method', [0x1f, 0x8b, 0x07, 0x00, 0, 0, 0, 0, 0, 3], 'unknown compression method'],
    ['reserved gzip flags', [0x1f, 0x8b, 0x08, 0x20, 0, 0, 0, 0, 0, 3], 'unknown header flags set']
  ])('reports %s', (_name, bytes, message) => {
    const strm = initializedStream(Buffer.from(bytes), 64, 31);
    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_DATA_ERROR);
    expect(strm.msg).toBe(message);
  });

  it('rejects header requests for non-gzip or invalid streams', () => {
    expect(inflateApi.inflateGetHeader(null, {})).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateGetHeader({}, {})).toBe(Z_STREAM_ERROR);

    const zlibStrm = initializedStream(zlib.deflateSync(Buffer.from('x')), 16, 15);
    const header = { done: true };
    expect(inflateApi.inflateGetHeader(zlibStrm, header)).toBe(Z_STREAM_ERROR);
    expect(header.done).toBe(true);
  });
});

describe('dictionary handling', () => {
  const dictionary = Buffer.from('hello world dictionary');
  const dictionaryData = Buffer.from(
    'hello world from the dictionary hello world!'
  );

  it('requests a dictionary, rejects the wrong one, and accepts the right one', () => {
    const compressed = zlib.deflateSync(dictionaryData, { dictionary });
    const strm = initializedStream(compressed, dictionaryData.length + 64, 15);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_NEED_DICT);
    expect(strm.total_out).toBe(0);
    expect(strm.state.mode).toBe(11); // DICT

    expect(inflateApi.inflateSetDictionary(strm, Buffer.from('wrong'))).toBe(Z_DATA_ERROR);
    expect(strm.state.mode).toBe(11);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);
    expect(strm.state.havedict).toBe(1);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(dictionaryData)).toBe(true);
  });

  it('accepts a preset dictionary for a raw deflate stream', () => {
    const compressed = zlib.deflateRawSync(dictionaryData, { dictionary });
    const strm = initializedStream(compressed, dictionaryData.length + 64, -15);

    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_OK);
    expect(strm.state.havedict).toBe(1);
    expect(strm.state.window).toBeInstanceOf(Uint8Array);
    expect(strm.state.whave).toBe(dictionary.length);

    expect(inflateApi.inflate(strm, Z_FINISH)).toBe(Z_STREAM_END);
    expect(producedBytes(strm).equals(dictionaryData)).toBe(true);
  });

  it('rejects dictionary calls at the wrong time or without a state', () => {
    expect(inflateApi.inflateSetDictionary(null, dictionary)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateSetDictionary({}, dictionary)).toBe(Z_STREAM_ERROR);

    const compressed = zlib.deflateSync(dictionaryData);
    const strm = initializedStream(compressed, dictionaryData.length + 64, 15);
    expect(inflateApi.inflateSetDictionary(strm, dictionary)).toBe(Z_STREAM_ERROR);
  });
});

describe('ending an inflate stream', () => {
  it('releases the state and sliding window', () => {
    const strm = initializedStream(Buffer.alloc(0), 32, -15);
    expect(inflateApi.inflateSetDictionary(strm, Buffer.from('dictionary'))).toBe(Z_OK);
    const state = strm.state;
    expect(state.window).not.toBeNull();

    expect(inflateApi.inflateEnd(strm)).toBe(Z_OK);
    expect(strm.state).toBeNull();
    expect(state.window).toBeNull();
    expect(inflateApi.inflateEnd(strm)).toBe(Z_STREAM_ERROR);
  });

  it('rejects invalid streams', () => {
    expect(inflateApi.inflateEnd(null)).toBe(Z_STREAM_ERROR);
    expect(inflateApi.inflateEnd({})).toBe(Z_STREAM_ERROR);
  });
});
